INSERT INTO `klien_posko` (`id_posko`, `nama_usaha`, `nama_penerima`, `jenis_kelamin`, `nama_pendamping`, `mulai_berdiri`, `jumlah_anggota`, `alamat`, `kabupaten`, `telepon`, `email`, `photo`, `logo`, `jenis_usaha`, `jenis_usaha_rinci`, `deskripsi_jenis_usaha`, `siup`, `npwp`, `tdp`, `pirt`, `nama_bank`, `no_rek_bank`, `nama_di_rek`, `peta_google`, `tgl_inp`, `log`) VALUES
(1, 'CAREPPE INDONESIA', 'Firial Mufidah Syafei', 'Ibu', 'Adiansyah', '2016', 3, 'Perumahan Manyingarri Blok A10 No 14', 'Takalar', '085342457574', 'firiyalmufidah@gmail.com', 'Firial Mufidah.jpg', 'tamaroca indah.jpg', 'Produk', 'Makanan Ringan', '-', '-', '-', '-', '-', '-', '-', '-', 'https://www.google.co.id/maps/@-5.2243249,119.4018824,16z', '18 Apr 2017 09:15:15', 'Anshar Ahmad'),
(2, 'Cahaya Desa', 'Muhammad Nasrul', 'Bpk', 'Dinas Perikanan Kab. Pangkep', '2012', 15, 'Jl. Andi Baso Oling Desa Pitue, Kec. Ma’rang  Kab. Pangkep', 'Pangkep', '082199499080', '-', 'Nasir.jpg', 'cahaya_desa.jpg', 'Produk', 'Perikanan dan Kelautan ( kerupuk bandeng, kerupuk udang, kerupuk rumput laut dan kerupuk kepiting)', 'Ide Awal \r\nDalam pengelolaan lingkungan  di wilayah pesisir isu utamanya adalah masih sangat besarnya jumlah masyarakat yang kurang mampu (penghasilan dibawah standar) dan masih harus menghadapi masalah kesehatan, air bersih bahkan sulit mendapat pendidikan yang layak. Hal ini disebabkan belum dikelola dengan baik sumberdaya alam dan sumber daya manusia itu sendiri.\r\nKabupaten pangkajene dan Kepulauan adalah Daerah Penghasil Perikanan dan Kelautan terbesar di Sulawesi Selatan meliputi SUMBER DAYA ALAM DAERAH seperti IKAN BANDENG, UDANG, KEPITING DAN RUMPUT LAUT dan komoditi andalan ini sangat melimpah.\r\n\r\nDan pada saat itu saya berinisiatif untuk menggerakkan masyarakat pesisir Dan masyrakat pulau terkait denganpengelolaan sumber daya alam dan sumber daya manusia, dengan membentuk kelompok usaha hasil perikanan CAHAYA DESA tepatnya pada tanggal 29 Januari 2011. Terbentuknya kelompok usaha ini dimulai dengan berbagai pelatihan-pelatihan yang diajarkan kepada anggota kelompok yang ilmunya diperoleh dari media internet, seperti pengolahan bandeng fresto, nugget bandeng, bandeng tanpa duri, kerupuk kepiting, dan kacang bandeng kentucky. Disamping itu berbagai produk  diproduksi yang berasal dari makanan tradisional bugis yang dikombinasikan dengan berbagai campuran-campuran produk hasil perikanan dan kelautan . Melalui kegiatan usaha pengolahaan hasil perikanan ini, sangan mendorong dan menunjang peningkatan ekonomi keluarga yang dulunya pendapatan keluarga hanya diperoleh oleh suami, namun dengan adanya pelibatan perembuan/istri dalam kegiatan usaha kelompok  mereka mengakui terjadinya peningkatan penghasilan ekonomi dalam keluarga.\r\n\r\nKeunggulan\r\nProduk andalan cahaya desa digemari oleh banyak kalangan karna selain rasanya yang khas bahan dasar pengolahanya berasalal dari sumber daya alam yang tersedia didesa ( ikan bandeng, udang, ikan gabus, kepiting) yang tentu makanan olahan ini sehat selain itu produk kami punya kesan tersendiri dibandingkan dengan produk yang tersebar di toko toko, proses produksinya yang alami sampai bahan dasarnya alami dari SDA setempat sehingga kami tidak pernah kewalahan dalam mencari bahan dasar olahan kami disamping itu berbagai olahan kami cukup menarik dan hanya kami yang membuat produk ini seperti snack kacang bandeng, kerupuk kepiting, nugget bandeng , sehingga itu yang membuat produk kami eksis. \r\n', '-', '-', '-', '-', '-', '-', '-', '-', '18 Apr 2017 09:37:11', 'Irsyadi Siradjuddin'),
(81, 'Ywtw', 'Ywtw', 'Bpk', 'Twtwt', '1992', 222, 'Ywywy', 'Makassar', '626262622', 'notini4361@chansd.com', NULL, NULL, 'Produk', 'Twtw', 'Wtwtw', '7272726262', '6226666', '72277272', '2626263663', 'Twtw', 'Twtw', '2627262626626', 'Gegehehewg', '08 Jan 2025 01:01:41', 'Irsyadi Siradjuddin'),
(4, 'IKM LARS', 'ARIE HIJRIYAH', 'Ibu', 'PUADY HAMMING', '2014', 2, 'BUMI PERMATA SUDIANG BLOK F6/15\r\nMAKASSAR – SULAWESI SELATAN\r\n', 'Makassar', '0813 4482 4482', NULL, 'Arie Hijriah.jpg', 'ume.jpg', 'Produk', 'KERUPUK RUMPUT LAUT, UME', 'Ide awal bermula dari pelatihan pengolahan kerupuk rumput laut yang diadakan oleh Inkubator Ati Makassar yang bekerja sama dengan PUPUK reacts, dengan sedikit inovasi maka kami memproduksi kerupuk rumput laut  yang dapat dikonsumsi kapan saja bahkan dapat dijadikan sebagai lauk tambahan saat makan nasi.\r\n\r\nKerupuk rumput laut kami meskipun masih perlu pengembangan dibeberapa segi, namun kami berupaya tetap memberikan kualitas yang terbaik.\r\n\r\nKeunggulan  dari Kerupuk kami ini adalah tambahan rumput laut dan rempah alami sehingga aman bagi anda yang alergi pada ikan maupun udang, sehingga lebih bermanfaat bagi kesehatan tubuh.\r\n', '-', '-', '-', '-', 'BRI', '0403-01-004861-53-9', 'Arie Hijriyah', '-', '18 Apr 2017 09:58:42', 'Anshar Ahmad'),
(5, 'Mitra Mandiri', 'Boedi Sardjana Julianto', 'Bpk', '-', '2017', 3, 'Sudiang Makassar', 'Makassar', '08114443738', 'boedi.julianto@gmail.com', 'Boedi.jpg', 'mitra_mandiri 91.jpg', 'Produk', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '18 Apr 2017 10:10:14', 'Irsyadi Siradjuddin'),
